import React from "react";
import { motion } from "framer-motion";
import { Package, MapPin, CheckCircle, Clock } from "lucide-react";

function Orders() {
  // Example orders (replace with API data)
  const orders = [
    {
      id: "ORD123",
      customer: "Rahul Sharma",
      address: "123, MG Road, Hyderabad",
      status: "Pending",
      amount: "₹450",
    },
    {
      id: "ORD124",
      customer: "Sneha Reddy",
      address: "45, Banjara Hills, Hyderabad",
      status: "In Transit",
      amount: "₹780",
    },
    {
      id: "ORD125",
      customer: "Amit Kumar",
      address: "9-8, Jubilee Hills, Hyderabad",
      status: "Delivered",
      amount: "₹1200",
    },
  ];

  return (
    <div style={pageStyle}>
      {/* Header */}
      <motion.div
        style={headerStyle}
        initial={{ opacity: 0, y: -50 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <Package style={{ width: "45px", height: "45px", color: "#fff" }} />
        <h1 style={headerTitle}>My Orders</h1>
        <p style={headerSubtitle}>Track and manage your assigned deliveries</p>
      </motion.div>

      {/* Orders List */}
      <div style={ordersWrapper}>
        {orders.map((order, index) => (
          <motion.div
            key={order.id}
            style={orderCard}
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: index * 0.2 }}
            whileHover={{ scale: 1.02 }}
            viewport={{ once: true }}
          >
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <h2 style={orderId}>{order.id}</h2>
              <span style={orderAmount}>{order.amount}</span>
            </div>
            <p style={customerName}>👤 {order.customer}</p>
            <p style={orderAddress}>
              <MapPin size={16} style={{ marginRight: "6px" }} />
              {order.address}
            </p>

            {/* Status */}
            <div style={statusWrapper(order.status)}>
              {order.status === "Delivered" ? (
                <CheckCircle size={18} />
              ) : (
                <Clock size={18} />
              )}
              <span>{order.status}</span>
            </div>

            {/* Actions */}
            {order.status !== "Delivered" && (
              <div style={actionsWrapper}>
                <button style={actionButton}>Start Delivery</button>
                <button style={{ ...actionButton, background: "#16a34a" }}>
                  Mark Delivered
                </button>
              </div>
            )}
          </motion.div>
        ))}
      </div>

      {/* Responsive CSS */}
      <style>{`
        @media (max-width: 768px) {
          h1 {
            font-size: 1.6rem !important;
          }
          h2 {
            font-size: 1.1rem !important;
          }
          div[style*="padding: 2rem"] {
            padding: 1rem !important;
          }
        }
      `}</style>
    </div>
  );
}

/* ---------- Styles ---------- */
const pageStyle = {
  background: "#f9fafb",
  minHeight: "100vh",
  fontFamily: "Inter, sans-serif",
  paddingBottom: "2rem",
};

const headerStyle = {
  background: "linear-gradient(135deg, #2563eb, #1e40af)",
  padding: "2.5rem 1rem",
  textAlign: "center",
  color: "#fff",
  borderBottomLeftRadius: "20px",
  borderBottomRightRadius: "20px",
  boxShadow: "0 6px 16px rgba(0,0,0,0.2)",
};

const headerTitle = {
  fontSize: "2rem",
  fontWeight: "700",
  margin: "1rem 0 0.3rem",
};

const headerSubtitle = {
  fontSize: "1rem",
  opacity: 0.9,
};

const ordersWrapper = {
  maxWidth: "900px",
  margin: "2rem auto",
  padding: "0 1rem",
  display: "grid",
  gap: "1.5rem",
};

const orderCard = {
  background: "#fff",
  padding: "1.5rem",
  borderRadius: "12px",
  boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
  transition: "all 0.3s ease",
};

const orderId = {
  fontSize: "1.2rem",
  fontWeight: "600",
  color: "#111827",
};

const orderAmount = {
  fontSize: "1rem",
  fontWeight: "700",
  color: "#2563eb",
};

const customerName = {
  fontSize: "1rem",
  margin: "0.5rem 0",
  fontWeight: "500",
};

const orderAddress = {
  display: "flex",
  alignItems: "center",
  fontSize: "0.95rem",
  color: "#374151",
};

const statusWrapper = (status) => ({
  marginTop: "1rem",
  display: "flex",
  alignItems: "center",
  gap: "6px",
  padding: "0.5rem 1rem",
  borderRadius: "8px",
  background:
    status === "Delivered"
      ? "rgba(34,197,94,0.15)"
      : "rgba(251,191,36,0.15)",
  color: status === "Delivered" ? "#16a34a" : "#b45309",
  fontWeight: "600",
  width: "fit-content",
});

const actionsWrapper = {
  marginTop: "1rem",
  display: "flex",
  gap: "1rem",
};

const actionButton = {
  flex: 1,
  padding: "0.7rem",
  borderRadius: "8px",
  border: "none",
  background: "#2563eb",
  color: "#fff",
  fontWeight: "600",
  cursor: "pointer",
  transition: "all 0.3s",
};

export default Orders;
